            Tx("أسهم المضاربة تُزكّى بقيمتها السوقية كعروض التجارة، وأسهم الاستثمار طويل الأجل تُزكّى بقدر ما يقابلها من الأموال الزكوية في الشركة، كما قرر مجمع الفقه الإسلامي الدولي.",
                "Shares bought for trading are valued at market price like trade goods; long-term shares owe zakat on their portion of the company's zakatable assets, as decided by the International Islamic Fiqh Academy.",
                fr = "Les actions achetées pour le négoce sont évaluées au prix du marché comme les marchandises ; les actions à long terme doivent la zakat sur leur part des actifs de l'entreprise soumis à la zakat, comme l'a décidé l'Académie internationale du fiqh islamique.",
                tr = "Alım satım için alınan hisseler ticaret malı gibi piyasa değeriyle değerlenir; uzun vadeli hisseler ise şirketin zekâta tabi varlıklarındaki paylarına göre zekâta tabidir. Uluslararası İslam Fıkıh Akademisi böyle karar vermiştir.",
                ur = "تجارت کے لیے خریدے گئے شیئرز کی مال تجارت کی طرح بازاری قیمت لگائی جاتی ہے؛ طویل مدتی شیئرز پر کمپنی کے قابل زکوٰۃ اثاثوں میں ان کے حصے کے بقدر زکوٰۃ ہے، جیسا کہ بین الاقوامی اسلامی فقہ اکیڈمی نے فیصلہ کیا۔",
                id = "Saham yang dibeli untuk diperdagangkan dinilai dengan harga pasar seperti barang dagangan; saham jangka panjang dizakati sesuai bagiannya dari aset wajib zakat perusahaan, sebagaimana diputuskan oleh Akademi Fikih Islam Internasional.",
                ms = "Saham yang dibeli untuk didagangkan dinilai pada harga pasaran seperti barang dagangan; saham jangka panjang dizakatkan mengikut bahagiannya daripada aset syarikat yang wajib dizakat, sebagaimana diputuskan oleh Akademi Fiqh Islam Antarabangsa.",
                fa = "سهامی که برای معامله خریداری شده، مانند کالای تجاری به قیمت بازار ارزش‌گذاری می‌شود؛ و سهام بلندمدت به اندازه سهمش از دارایی‌های مشمول زکات شرکت زکات دارد، چنان‌که مجمع بین‌المللی فقه اسلامی مقرر کرده است.",
                bn = "ব্যবসার উদ্দেশ্যে কেনা শেয়ারের মূল্য ব্যবসায়িক পণ্যের মতো বাজারদরে নির্ধারিত হয়; দীর্ঘমেয়াদি শেয়ারে কোম্পানির যাকাতযোগ্য সম্পদে তার অংশ অনুযায়ী যাকাত দিতে হয়, যেমনটি আন্তর্জাতিক ইসলামি ফিকহ একাডেমি সিদ্ধান্ত দিয়েছে।",
                ru = "Акции, купленные для торговли, оцениваются по рыночной цене как товары; с долгосрочных акций закят выплачивается с их доли в облагаемых закятом активах компании, как постановила Международная академия исламского фикха.",
                de = "Zum Handeln gekaufte Aktien werden wie Handelswaren zum Marktpreis bewertet; auf langfristige Aktien ist Zakat auf ihren Anteil am zakatpflichtigen Vermögen des Unternehmens fällig, wie die Internationale Islamische Fiqh-Akademie beschlossen hat.",
                es = "Las acciones compradas para negociar se valoran a precio de mercado como las mercancías; las acciones a largo plazo deben zakat por su parte de los activos de la empresa sujetos a zakat, según decidió la Academia Internacional de Fiqh Islámico.",
                uk = "Акції, куплені для торгівлі, оцінюються за ринковою ціною як товари; з довгострокових акцій закят сплачується з їхньої частки в активах компанії, що підлягають закяту, як ухвалила Міжнародна академія ісламського фікху."),
