                tr = "Hayvanların otlaması şartı",
                ur = "جانوروں کا چرنے والا ہونا",
                id = "Ternak harus digembalakan",
                ms = "Ternakan mesti diragut bebas",
                fa = "چرنده بودن دام",
                bn = "পশু চারণভূমিতে চরা জরুরি",
                ru = "Животные должны пастись",
                de = "Die Tiere müssen weiden",
                es = "Los animales deben pastar",
                uk = "Тварини мають пастися"),
            Tx("السائمة التي ترعى الكلأ المباح أكثر العام، وعليه الجمهور، فلا زكاة في المعلوفة ولا العوامل، وأوجبها المالكية فيهما. وما أُعدّ للتجارة يُزكّى زكاة عروض التجارة بقيمته.",
                "They must graze on open pasture most of the year, per the majority, so stall-fed and working animals owe nothing; the Malikis require it on these too. Animals held for sale are valued as trade goods.",
                fr = "Selon la majorité, ils doivent paître en pâturage libre la plus grande partie de l'année ; les animaux nourris à l'étable et les bêtes de travail ne doivent donc rien, mais les malékites l'exigent aussi pour ceux-ci. Les animaux destinés à la vente sont évalués comme des marchandises.",
                tr = "Cumhura göre hayvanlar yılın çoğunda serbest merada otlamalıdır; ahırda beslenen ve iş hayvanlarına zekât düşmez. Mâlikîler bunlara da zekâtı farz görür. Satış için tutulan hayvanlar ticaret malı olarak değerlenir.",
                ur = "جمہور کے نزدیک جانور سال کا اکثر حصہ کھلی چراگاہ میں چرنے والے ہوں، لہٰذا گھر پر چارہ کھانے والے اور کام کاج کے جانوروں پر کچھ نہیں؛ مالکیہ ان میں بھی زکوٰۃ واجب کہتے ہیں۔ فروخت کے لیے رکھے جانوروں کی مال تجارت کی طرح قیمت لگائی جاتی ہے۔",
                id = "Menurut jumhur, ternak harus digembalakan di padang rumput bebas hampir sepanjang tahun, sehingga ternak yang diberi pakan di kandang dan ternak pekerja tidak dizakati; mazhab Maliki mewajibkannya juga pada keduanya. Hewan yang disiapkan untuk dijual dinilai sebagai barang dagangan.",
                ms = "Menurut jumhur, ternakan mesti meragut di padang terbuka sepanjang sebahagian besar tahun, maka ternakan yang diberi makan di kandang dan ternakan pekerja tidak dikenakan zakat; mazhab Maliki mewajibkannya juga ke atas keduanya. Binatang yang disimpan untuk dijual dinilai sebagai barang dagangan.",
                fa = "به نظر جمهور، دام باید بیشتر سال در چراگاه آزاد بچرد؛ پس در دام علوفه‌خوار و دام کاری زکاتی نیست، و مالکیه در آن‌ها نیز زکات را واجب می‌دانند. دامی که برای تجارت نگهداری می‌شود، مانند کالای تجاری به ارزشش زکات دارد.",
                bn = "জমহুরের মতে, পশু বছরের বেশির ভাগ সময় উন্মুক্ত চারণভূমিতে চরতে হবে; তাই ঘরে খাওয়ানো পশু ও কাজের পশুতে কিছু নেই; মালেকিরা এগুলোতেও যাকাত ফরজ বলেন। বিক্রির জন্য রাখা পশুর মূল্য ব্যবসায়িক পণ্যের মতো ধরা হয়।",
                ru = "По мнению большинства, они должны пастись на вольном пастбище большую часть года, поэтому со скота на стойловом содержании и рабочих животных ничего не причитается; маликиты обязывают закят и с них. Животные, предназначенные для продажи, оцениваются как товары.",
                de = "Nach der Mehrheit müssen sie den größten Teil des Jahres auf freier Weide grasen, sodass für im Stall gefütterte Tiere und Arbeitstiere nichts fällig ist; die Malikiten verlangen sie auch auf diese. Zum Verkauf gehaltene Tiere werden als Handelswaren bewertet.",
                es = "Según la mayoría, deben pastar en pastos libres la mayor parte del año, así que los animales alimentados en establo y los de trabajo no deben nada; los malikíes la exigen también sobre estos. Los animales destinados a la venta se valoran como mercancías.",
                uk = "За думкою більшості, вони мають пастися на вільному пасовищі більшу частину року, тож із худоби на стійловому утриманні та робочих тварин нічого не належить; малікіти зобов'язують закят і з них. Тварин, призначених для продажу, оцінюють як товари."),
