                ur = "بنت مخاض: ایک سالہ اونٹنی؛ بنت لبون: دو سالہ؛ حِقّہ: تین سالہ؛ جذعہ: چار سالہ۔ تبیع (گائے): ایک سالہ؛ مسنّہ: دو سالہ۔ شاۃ: چھ ماہ کی بھیڑ یا ایک سال کی بکری۔",
