                fa = "بنت مخاض: شتر ماده یک‌ساله؛ بنت لبون: دوساله؛ حِقّه: سه‌ساله؛ جذعه: چهارساله. تبیع (گاو): یک‌ساله؛ مُسِنّه: دوساله. شاة: گوسفند شش‌ماهه یا بز یک‌ساله.",
