                bn = "বৃষ্টি বা ঝরনার মাধ্যমে বিনা খরচে সেচ হলে এক-দশমাংশ (10%); খরচ করে সেচ হলে এক-দশমাংশের অর্ধেক (5%); দুইভাবে অর্ধেক অর্ধেক হলে এক-দশমাংশের তিন-চতুর্থাংশ (7.5%)।",
