            Tx("إطعام عشرة مساكين من أوسط طعام الأهل، أو كسوتهم، أو عتق رقبة، فمن لم يجد صام ثلاثة أيام.",
                "Feed ten poor people with the average food of your household, or clothe them, or free a slave; whoever cannot, fasts three days.",
                fr = "Nourrir dix pauvres de la nourriture moyenne de votre foyer, ou les vêtir, ou affranchir un esclave ; qui ne le peut pas jeûne trois jours.",
                tr = "Ailenize yedirdiğinizin ortalamasından on fakiri doyurmak, onları giydirmek veya bir köle azat etmek; buna gücü yetmeyen üç gün oruç tutar.",
                ur = "اپنے گھر والوں کے اوسط درجے کے کھانے سے دس مسکینوں کو کھانا کھلانا، یا انہیں کپڑے پہنانا، یا ایک غلام آزاد کرنا؛ جو اس کی استطاعت نہ رکھے وہ تین دن روزے رکھے۔",
                id = "Memberi makan sepuluh orang miskin dengan makanan yang biasa Anda berikan kepada keluarga, atau memberi mereka pakaian, atau memerdekakan budak; yang tidak mampu, berpuasa tiga hari.",
                ms = "Memberi makan sepuluh orang miskin dengan makanan pertengahan yang biasa diberikan kepada keluarga anda, atau memberi mereka pakaian, atau memerdekakan hamba; sesiapa yang tidak mampu, berpuasa tiga hari.",
                fa = "اطعام ده مسکین از غذای متوسط خانواده‌تان، یا پوشاندن آنان، یا آزاد کردن یک برده؛ هر که نتواند، سه روز روزه بگیرد.",
                bn = "নিজ পরিবারকে যে মধ্যম মানের খাবার খাওয়ান তা থেকে দশজন মিসকিনকে খাওয়ানো, অথবা তাদের বস্ত্র দেওয়া, অথবা একজন দাস মুক্ত করা; যে অক্ষম, সে তিন দিন রোজা রাখবে।",
                ru = "Накормить десять бедняков средней пищей, которой вы кормите свою семью, или одеть их, или освободить раба; кто не может — постится три дня.",
                de = "Zehn Bedürftige mit dem durchschnittlichen Essen deines Haushalts speisen, sie kleiden oder einen Sklaven befreien; wer das nicht kann, fastet drei Tage.",
                es = "Alimentar a diez pobres con la comida media de tu familia, o vestirlos, o liberar a un esclavo; quien no pueda, ayuna tres días.",
                uk = "Нагодувати десятьох бідняків середньою їжею, якою ви годуєте свою родину, або одягнути їх, або звільнити раба; хто не може — постить три дні."),
