                bn = "ক্রমানুসারে: একজন দাস মুক্ত করা; সম্ভব না হলে লাগাতার দুই মাস রোজা রাখা; তাতে অক্ষম হলে ষাটজন মিসকিনকে খাওয়ানো — সঙ্গে সেই দিনের কাজা।",
