    /** شرح آيات المواريث وكيفية القسمة: الآيات الثلاث بنصها، ثم السنة والإجماع فيما لم تفصّله */
    val inheritance = listOf(
        f(ProofKind.CONSENSUS, "order",
            Tx("خطوات القسمة", "How the estate is divided",
                fr = "Les étapes du partage",
                tr = "Terikenin taksim adımları",
                ur = "تقسیم ترکہ کے مراحل",
                id = "Langkah-langkah pembagian warisan",
                ms = "Langkah-langkah pembahagian pusaka",
                fa = "مراحل تقسیم ترکه",
                bn = "সম্পত্তি বণ্টনের ধাপ",
                ru = "Порядок раздела наследства",
                de = "Wie der Nachlass geteilt wird",
                es = "Cómo se reparte la herencia",
                uk = "Порядок поділу спадщини"),
            Tx("١) تُخرج من التركة نفقات التجهيز والدفن، ثم الديون، ثم الوصية لغير وارث في حدود الثلث. ٢) يُعطى أصحاب الفروض أنصبتهم المقدّرة في القرآن: النصف والربع والثمن والثلثان والثلث والسدس. ٣) ما بقي يأخذه العصبة، الأقرب فالأقرب. ٤) يُحجب الأبعد بالأقرب. ٥) إن زادت الفروض على التركة نقصت كلها بنسبتها (العول)، وإن بقي شيء ولا عصبة رُدّ على أصحاب الفروض غير الزوجين (الرد).",
                "1) From the estate, pay the funeral costs, then debts, then any bequest to a non-heir up to one third. 2) Give those with fixed shares their Quranic portions: a half, a quarter, an eighth, two thirds, a third and a sixth. 3) What remains goes to the agnatic heirs ('asabah), nearest first. 4) Nearer relatives exclude more distant ones. 5) If the shares exceed the estate, all are reduced in proportion ('awl); if something is left and there is no 'asabah, it returns to the sharers other than the spouses (radd).",
                fr = "1) On prélève de la succession les frais funéraires, puis les dettes, puis tout legs à un non-héritier dans la limite d'un tiers. 2) On donne aux détenteurs de parts fixes leurs portions coraniques : la moitié, le quart, le huitième, les deux tiers, le tiers et le sixième. 3) Le reste revient aux héritiers agnats ('asaba), les plus proches d'abord. 4) Les parents plus proches excluent les plus éloignés. 5) Si les parts dépassent la succession, toutes sont réduites proportionnellement ('awl) ; s'il reste quelque chose et qu'il n'y a pas de 'asaba, le reliquat revient aux détenteurs de parts fixes autres que les époux (radd).",
                tr = "1) Terikeden önce teçhiz ve defin masrafları, sonra borçlar, sonra mirasçı olmayana yapılan vasiyet üçte bir sınırında çıkarılır. 2) Farz pay sahiplerine Kur'an'da belirlenen payları verilir: yarım, dörtte bir, sekizde bir, üçte iki, üçte bir ve altıda bir. 3) Kalan asabeye verilir; en yakın olan önce gelir. 4) Daha yakın akraba, daha uzak olanı mirastan düşürür. 5) Paylar terikeyi aşarsa hepsi oranında azalır (avl); bir şey artar ve asabe bulunmazsa, artan kısım eşler dışındaki farz pay sahiplerine iade edilir (redd).",
                ur = "1) ترکے میں سے پہلے تجہیز و تدفین کے اخراجات، پھر قرض، پھر غیر وارث کے لیے وصیت ایک تہائی کی حد تک نکالی جائے۔ 2) اصحاب الفروض کو قرآن میں مقرر ان کے حصے دیے جائیں: نصف، چوتھائی، آٹھواں، دو تہائی، ایک تہائی اور چھٹا حصہ۔ 3) جو بچے وہ عصبہ کو ملے، جو زیادہ قریب ہو وہ پہلے۔ 4) زیادہ قریبی رشتہ دار دور والے کو محجوب کر دیتا ہے۔ 5) اگر حصے ترکے سے بڑھ جائیں تو سب اپنے تناسب سے کم ہو جاتے ہیں (عول)، اور اگر کچھ بچ جائے اور کوئی عصبہ نہ ہو تو میاں بیوی کے سوا اصحاب الفروض پر لوٹا دیا جاتا ہے (رد)۔",
                id = "1) Dari harta peninggalan, dibayarkan biaya pengurusan jenazah, lalu utang, lalu wasiat untuk bukan ahli waris paling banyak sepertiga. 2) Ashabul furudh diberi bagian yang ditetapkan Al-Qur'an: setengah, seperempat, seperdelapan, dua pertiga, sepertiga, dan seperenam. 3) Sisanya untuk 'asabah, yang terdekat lebih dahulu. 4) Kerabat yang lebih dekat menghalangi yang lebih jauh. 5) Jika jumlah bagian melebihi harta, semua bagian dikurangi secara proporsional ('aul); jika masih ada sisa dan tidak ada 'asabah, sisa dikembalikan kepada ashabul furudh selain suami atau istri (radd).",
                ms = "1) Daripada harta pusaka, dibayar kos pengurusan jenazah, kemudian hutang, kemudian wasiat kepada bukan waris setakat satu pertiga. 2) Ashab al-furud diberikan bahagian yang ditetapkan al-Quran: satu perdua, satu perempat, satu perlapan, dua pertiga, satu pertiga dan satu perenam. 3) Bakinya untuk asabah, yang paling hampir terlebih dahulu. 4) Kerabat yang lebih hampir mendinding yang lebih jauh. 5) Jika jumlah bahagian melebihi harta pusaka, semuanya dikurangkan mengikut nisbah ('aul); jika ada baki dan tiada asabah, baki dikembalikan kepada ashab al-furud selain suami isteri (radd).",
                fa = "1) از ترکه ابتدا هزینه‌های تجهیز و دفن، سپس بدهی‌ها، سپس وصیت برای غیر وارث تا سقف یک‌سوم پرداخت می‌شود. 2) به صاحبان فروض سهم‌های مقرر در قرآن داده می‌شود: نصف، یک‌چهارم، یک‌هشتم، دو سوم، یک‌سوم و یک‌ششم. 3) باقی‌مانده به عصبه می‌رسد، هر که نزدیک‌تر است مقدم است. 4) خویشاوند نزدیک‌تر، دورتر را محجوب می‌کند. 5) اگر سهام بیش از ترکه شود، همه به نسبت کاهش می‌یابند (عول)؛ و اگر چیزی باقی بماند و عصبه‌ای نباشد، به صاحبان فروض جز زن و شوهر بازگردانده می‌شود (رد).",
                bn = "1) পরিত্যক্ত সম্পত্তি থেকে প্রথমে কাফন-দাফনের খরচ, তারপর ঋণ, তারপর ওয়ারিশ নয় এমন কারও জন্য অসিয়ত এক-তৃতীয়াংশের মধ্যে আদায় করা হয়। 2) নির্ধারিত অংশের অধিকারীদের কুরআনে নির্ধারিত অংশ দেওয়া হয়: অর্ধেক, এক-চতুর্থাংশ, এক-অষ্টমাংশ, দুই-তৃতীয়াংশ, এক-তৃতীয়াংশ ও এক-ষষ্ঠাংশ। 3) অবশিষ্ট পায় আসাবা, নিকটতম আগে। 4) নিকটতর আত্মীয় দূরবর্তীকে বঞ্চিত করে। 5) অংশগুলো সম্পত্তির চেয়ে বেশি হলে সবগুলো আনুপাতিক হারে কমে যায় (আউল); আর কিছু অবশিষ্ট থাকলে এবং কোনো আসাবা না থাকলে তা স্বামী-স্ত্রী ছাড়া অন্য নির্ধারিত অংশের অধিকারীদের ফেরত দেওয়া হয় (রদ)।",
                ru = "1) Из наследства оплачиваются расходы на похороны, затем долги, затем завещание в пользу ненаследника в пределах трети. 2) Обладателям фиксированных долей выделяются их доли, установленные Кораном: половина, четверть, восьмая, две трети, треть и шестая. 3) Остаток получают наследники-агнаты (асаба), начиная с ближайших. 4) Более близкие родственники исключают более дальних. 5) Если доли превышают наследство, все они пропорционально уменьшаются (ауль); если что-то осталось и асаба нет, остаток возвращается обладателям фиксированных долей, кроме супругов (радд).",
                de = "1) Aus dem Nachlass werden die Bestattungskosten bezahlt, dann die Schulden, dann ein etwaiges Vermächtnis an Nicht-Erben bis zu einem Drittel. 2) Wer einen festen Anteil hat, erhält seinen im Koran bestimmten Anteil: die Hälfte, ein Viertel, ein Achtel, zwei Drittel, ein Drittel und ein Sechstel. 3) Der Rest geht an die agnatischen Erben ('Asaba), die nächsten zuerst. 4) Nähere Verwandte schließen entferntere aus. 5) Übersteigen die Anteile den Nachlass, werden alle verhältnismäßig gekürzt ('Aul); bleibt etwas übrig und gibt es keine 'Asaba, geht es an die Inhaber fester Anteile außer den Ehegatten zurück (Radd).",
                es = "1) De la herencia se pagan los gastos del funeral, luego las deudas y luego cualquier legado a quien no es heredero, hasta un tercio. 2) Los que tienen cuotas fijas reciben sus porciones coránicas: la mitad, un cuarto, un octavo, dos tercios, un tercio y un sexto. 3) Lo que queda va a los herederos agnados ('asaba), primero los más cercanos. 4) Los parientes más cercanos excluyen a los más lejanos. 5) Si las cuotas superan la herencia, todas se reducen proporcionalmente ('awl); si sobra algo y no hay 'asaba, se devuelve a los que tienen cuotas fijas, salvo los cónyuges (radd).",
                uk = "1) Зі спадщини оплачують витрати на поховання, потім борги, потім заповіт на користь неспадкоємця в межах третини. 2) Власникам фіксованих часток виділяють їхні частки, встановлені Кораном: половину, чверть, восьму, дві третини, третину й шосту. 3) Решту отримують спадкоємці-агнати (асаба), починаючи з найближчих. 4) Ближчі родичі усувають дальших. 5) Якщо частки перевищують спадщину, усі вони пропорційно зменшуються (ауль); якщо щось залишилося й асаба немає, залишок повертається власникам фіксованих часток, крім подружжя (радд)."),
            Tx("المغني لابن قدامة؛ الرحبية", "Ibn Qudamah, al-Mughni; al-Rahbiyyah",
                fr = "Ibn Qudama, al-Mughni ; ar-Rahbiyya",
                tr = "İbn Kudâme, el-Muğnî; er-Rahbiyye",
                ur = "ابن قدامہ، المغنی؛ الرحبیہ",
                id = "Ibnu Qudamah, al-Mughni; ar-Rahbiyyah",
                ms = "Ibn Qudamah, al-Mughni; al-Rahbiyyah",
                fa = "ابن قدامه، المغنی؛ الرحبیة",
                bn = "ইবনে কুদামা, আল-মুগনি; আর-রাহবিয়্যা",
                ru = "Ибн Кудама, «аль-Мугни»; «ар-Рахбийя»",
                de = "Ibn Qudama, al-Mughni; ar-Rahbiyya",
                es = "Ibn Qudama, al-Mughni; ar-Rahbiyya",
                uk = "Ібн Кудама, «аль-Мугні»; «ар-Рахбійя»")),
        q("family", 4, 11, 11,
            Tx("آية الأولاد والوالدين", "The verse of children and parents",
                fr = "Le verset des enfants et des parents",
                tr = "Çocuklar ve anne baba ayeti",
                ur = "اولاد اور والدین کی آیت",
                id = "Ayat tentang anak dan orang tua",
                ms = "Ayat anak-anak dan ibu bapa",
                fa = "آیه فرزندان و پدر و مادر",
                bn = "সন্তান ও পিতা-মাতার আয়াত",
                ru = "Аят о детях и родителях",
                de = "Der Vers über Kinder und Eltern",
                es = "La aya de los hijos y los padres",
                uk = "Аят про дітей і батьків"),
            Tx("الأولاد: للذكر مثل حظ الأنثيين. البنت الواحدة لها النصف، والبنتان فأكثر لهن الثلثان. الأب والأم: لكل منهما السدس إن كان للميت ولد. فإن لم يكن له ولد وورثه أبواه فللأم الثلث وللأب الباقي، فإن كان له إخوة (اثنان فأكثر) فللأم السدس. وكل ذلك بعد الوصية والدين.",
                "Children: a son receives twice a daughter's share. One daughter alone takes a half, two or more take two thirds. Father and mother: each takes a sixth if the deceased has children. If there are no children and the parents inherit, the mother takes a third and the father the rest; if the deceased has siblings (two or more), the mother takes a sixth. All of this is after any bequest and debt.",
                fr = "Enfants : le fils reçoit le double de la part d'une fille. Une fille seule prend la moitié, deux filles ou plus prennent les deux tiers. Père et mère : chacun prend un sixième si le défunt a des enfants. S'il n'a pas d'enfants et que ses parents héritent, la mère prend un tiers et le père le reste ; si le défunt a des frères et sœurs (deux ou plus), la mère prend un sixième. Tout cela après tout legs et toute dette.",
                tr = "Çocuklar: erkeğe kızın payının iki katı verilir. Tek kız yarımı, iki veya daha fazla kız üçte ikiyi alır. Anne ve baba: ölenin çocuğu varsa her birine altıda bir verilir. Çocuğu yoksa ve mirasçısı anne babası ise anneye üçte bir, babaya kalan verilir; ölenin kardeşleri (iki veya daha fazla) varsa anneye altıda bir verilir. Bunların hepsi vasiyet ve borçtan sonradır.",
                ur = "اولاد: لڑکے کا حصہ دو لڑکیوں کے برابر ہے۔ اکیلی بیٹی کو نصف، اور دو یا زیادہ بیٹیوں کو دو تہائی۔ ماں باپ: میت کی اولاد ہو تو ہر ایک کو چھٹا حصہ۔ اگر اولاد نہ ہو اور ماں باپ وارث ہوں تو ماں کو ایک تہائی اور باپ کو باقی؛ اور اگر میت کے بہن بھائی (دو یا زیادہ) ہوں تو ماں کو چھٹا حصہ۔ یہ سب وصیت اور قرض کے بعد ہے۔",
                id = "Anak: bagian anak laki-laki dua kali bagian anak perempuan. Satu anak perempuan saja mendapat setengah, dua atau lebih mendapat dua pertiga. Ayah dan ibu: masing-masing mendapat seperenam jika mayit memiliki anak. Jika mayit tidak memiliki anak dan yang mewarisinya kedua orang tuanya, ibu mendapat sepertiga dan ayah sisanya; jika mayit memiliki saudara (dua orang atau lebih), ibu mendapat seperenam. Semua itu setelah dipenuhi wasiat dan utang.",
                ms = "Anak-anak: bahagian anak lelaki dua kali bahagian anak perempuan. Seorang anak perempuan sahaja mendapat satu perdua, dua orang atau lebih mendapat dua pertiga. Bapa dan ibu: masing-masing mendapat satu perenam jika si mati mempunyai anak. Jika si mati tiada anak dan yang mewarisinya ibu bapanya, ibu mendapat satu pertiga dan bapa bakinya; jika si mati mempunyai adik-beradik (dua orang atau lebih), ibu mendapat satu perenam. Semua ini selepas wasiat dan hutang.",
                fa = "فرزندان: سهم پسر دو برابر سهم دختر است. یک دختر تنها نصف می‌برد و دو دختر یا بیشتر دو سوم. پدر و مادر: اگر متوفی فرزند داشته باشد، هر یک یک‌ششم می‌برند. اگر فرزند نداشته باشد و پدر و مادرش وارث او باشند، مادر یک‌سوم و پدر باقی را می‌برد؛ و اگر متوفی برادر و خواهر (دو نفر یا بیشتر) داشته باشد، مادر یک‌ششم می‌برد. همه این‌ها پس از وصیت و دین است.",
                bn = "সন্তান: পুত্র পায় কন্যার দ্বিগুণ। একমাত্র কন্যা পায় অর্ধেক, দুই বা ততোধিক কন্যা পায় দুই-তৃতীয়াংশ। পিতা ও মাতা: মৃত ব্যক্তির সন্তান থাকলে প্রত্যেকে এক-ষষ্ঠাংশ পান। সন্তান না থাকলে এবং পিতা-মাতা ওয়ারিশ হলে মাতা পান এক-তৃতীয়াংশ এবং পিতা অবশিষ্ট; আর মৃতের ভাইবোন (দুই বা ততোধিক) থাকলে মাতা পান এক-ষষ্ঠাংশ। এ সবই অসিয়ত ও ঋণ পরিশোধের পর।",
                ru = "Дети: сын получает вдвое больше дочери. Единственная дочь получает половину, две и более — две трети. Отец и мать: каждый получает шестую, если у умершего есть дети. Если детей нет и наследуют родители, мать получает треть, а отец — остаток; если у умершего есть братья и сёстры (двое и более), мать получает шестую. Всё это — после исполнения завещания и уплаты долга.",
                de = "Kinder: Ein Sohn erhält doppelt so viel wie eine Tochter. Eine einzige Tochter erhält die Hälfte, zwei oder mehr erhalten zwei Drittel. Vater und Mutter: Jeder erhält ein Sechstel, wenn der Verstorbene Kinder hat. Hat er keine Kinder und beerben ihn die Eltern, erhält die Mutter ein Drittel und der Vater den Rest; hat der Verstorbene Geschwister (zwei oder mehr), erhält die Mutter ein Sechstel. All dies gilt nach etwaigem Vermächtnis und Schulden.",
                es = "Hijos: el hijo recibe el doble de la parte de una hija. Una sola hija recibe la mitad; dos o más, dos tercios. Padre y madre: cada uno recibe un sexto si el difunto tiene hijos. Si no tiene hijos y le heredan sus padres, la madre recibe un tercio y el padre el resto; si el difunto tiene hermanos (dos o más), la madre recibe un sexto. Todo esto después de cualquier legado y deuda.",
                uk = "Діти: син отримує вдвічі більше за дочку. Єдина дочка отримує половину, дві й більше — дві третини. Батько й мати: кожен отримує шосту, якщо в померлого є діти. Якщо дітей немає й успадковують батьки, мати отримує третину, а батько — решту; якщо в померлого є брати й сестри (двоє й більше), мати отримує шосту. Усе це — після виконання заповіту й сплати боргу."),
            Tx("النساء: 11", "An-Nisa 4:11",
                fr = "An-Nisâ' 4:11",
                tr = "Nisâ 4:11",
                ur = "النساء 4:11",
                id = "An-Nisa' 4:11",
                ms = "An-Nisa' 4:11",
                fa = "نساء 4:11",
                bn = "আন-নিসা 4:11",
                ru = "Ан-Ниса 4:11",
                de = "An-Nisa' 4:11",
                es = "An-Nisá 4:11",
                uk = "Ан-Ніса 4:11")),
        q("share", 4, 12, 12,
            Tx("آية الزوجين والإخوة لأم", "The verse of spouses and maternal siblings",
                fr = "Le verset des époux et des frères et sœurs utérins",
                tr = "Eşler ve anne bir kardeşler ayeti",
                ur = "میاں بیوی اور ماں شریک بہن بھائیوں کی آیت",
                id = "Ayat tentang suami istri dan saudara seibu",
                ms = "Ayat suami isteri dan saudara seibu",
                fa = "آیه زن و شوهر و برادران و خواهران مادری",
                bn = "স্বামী-স্ত্রী ও বৈপিত্রেয় ভাইবোনের আয়াত",
                ru = "Аят о супругах и единоутробных братьях и сёстрах",
                de = "Der Vers über Ehegatten und Halbgeschwister mütterlicherseits",
                es = "La aya de los cónyuges y los medio hermanos maternos",
                uk = "Аят про подружжя та єдиноутробних братів і сестер"),
            Tx("الزوج: النصف إن لم يكن للزوجة ولد، والربع إن كان لها ولد. الزوجة: الربع إن لم يكن للزوج ولد، والثمن إن كان له ولد، وتشترك فيه الزوجات. الإخوة لأم في الكلالة: للواحد السدس، ولاثنين فأكثر الثلث يقتسمونه بالتساوي ذكرهم كأنثاهم.",
                "Husband: a half if the wife has no children, a quarter if she has. Wife: a quarter if the husband has no children, an eighth if he has; several wives share it. Maternal siblings in kalalah: one takes a sixth, two or more share a third equally, males and females alike.",
                fr = "Mari : la moitié si l'épouse n'a pas d'enfants, le quart si elle en a. Épouse : le quart si le mari n'a pas d'enfants, le huitième s'il en a ; plusieurs épouses se le partagent. Frères et sœurs utérins en cas de kalala : un seul prend un sixième, deux ou plus se partagent un tiers à parts égales, hommes et femmes de même.",
                tr = "Koca: karısının çocuğu yoksa yarım, varsa dörtte bir. Karı: kocasının çocuğu yoksa dörtte bir, varsa sekizde bir; birden fazla karı bunu paylaşır. Kelâlede anne bir kardeşler: tek ise altıda bir; iki veya daha fazla ise erkek kadın farkı olmaksızın üçte biri eşit olarak paylaşırlar.",
                ur = "شوہر: بیوی کی اولاد نہ ہو تو نصف، اور اولاد ہو تو چوتھائی۔ بیوی: شوہر کی اولاد نہ ہو تو چوتھائی، اور اولاد ہو تو آٹھواں حصہ؛ کئی بیویاں ہوں تو اسی میں شریک ہوں گی۔ کلالہ میں ماں شریک بہن بھائی: ایک ہو تو چھٹا حصہ، دو یا زیادہ ہوں تو ایک تہائی میں برابر کے شریک، مرد و عورت یکساں۔",
                id = "Suami: setengah jika istri tidak memiliki anak, seperempat jika memiliki anak. Istri: seperempat jika suami tidak memiliki anak, seperdelapan jika memiliki anak; beberapa istri berbagi bagian itu. Saudara seibu dalam kalalah: satu orang mendapat seperenam, dua orang atau lebih berbagi sepertiga sama rata, laki-laki dan perempuan sama.",
                ms = "Suami: satu perdua jika isteri tiada anak, satu perempat jika ada anak. Isteri: satu perempat jika suami tiada anak, satu perlapan jika ada anak; beberapa isteri berkongsi bahagian itu. Saudara seibu dalam kalalah: seorang mendapat satu perenam, dua orang atau lebih berkongsi satu pertiga sama rata, lelaki dan perempuan sama.",
                fa = "شوهر: اگر زن فرزند نداشته باشد نصف، و اگر داشته باشد یک‌چهارم. زن: اگر شوهر فرزند نداشته باشد یک‌چهارم، و اگر داشته باشد یک‌هشتم؛ و چند همسر در آن شریک‌اند. برادران و خواهران مادری در کلاله: یک نفر یک‌ششم، و دو نفر یا بیشتر یک‌سوم را به تساوی تقسیم می‌کنند، مرد و زن یکسان.",
                bn = "স্বামী: স্ত্রীর সন্তান না থাকলে অর্ধেক, থাকলে এক-চতুর্থাংশ। স্ত্রী: স্বামীর সন্তান না থাকলে এক-চতুর্থাংশ, থাকলে এক-অষ্টমাংশ; একাধিক স্ত্রী থাকলে তারা তাতে শরিক হন। কালালার ক্ষেত্রে বৈপিত্রেয় ভাইবোন: একজন হলে এক-ষষ্ঠাংশ, দুই বা ততোধিক হলে এক-তৃতীয়াংশ সমানভাবে ভাগ করে নেয়, নারী-পুরুষ সমান।",
                ru = "Муж: половина, если у жены нет детей, и четверть, если есть. Жена: четверть, если у мужа нет детей, и восьмая, если есть; несколько жён делят её между собой. Единоутробные братья и сёстры при калале: один получает шестую, двое и более делят треть поровну, мужчины и женщины одинаково.",
                de = "Ehemann: die Hälfte, wenn die Ehefrau keine Kinder hat, ein Viertel, wenn sie welche hat. Ehefrau: ein Viertel, wenn der Ehemann keine Kinder hat, ein Achtel, wenn er welche hat; mehrere Ehefrauen teilen es sich. Halbgeschwister mütterlicherseits bei Kalala: Eines erhält ein Sechstel, zwei oder mehr teilen sich ein Drittel zu gleichen Teilen, männliche wie weibliche.",
                es = "Esposo: la mitad si la esposa no tiene hijos, un cuarto si los tiene. Esposa: un cuarto si el esposo no tiene hijos, un octavo si los tiene; varias esposas lo comparten. Medio hermanos maternos en caso de kalala: uno recibe un sexto; dos o más comparten un tercio a partes iguales, varones y mujeres por igual.",
                uk = "Чоловік: половина, якщо в дружини немає дітей, і чверть, якщо є. Дружина: чверть, якщо в чоловіка немає дітей, і восьма, якщо є; кілька дружин ділять її між собою. Єдиноутробні брати й сестри за калали: один отримує шосту, двоє й більше ділять третину порівну, чоловіки й жінки однаково."),
            Tx("النساء: 12", "An-Nisa 4:12",
                fr = "An-Nisâ' 4:12",
                tr = "Nisâ 4:12",
                ur = "النساء 4:12",
                id = "An-Nisa' 4:12",
                ms = "An-Nisa' 4:12",
                fa = "نساء 4:12",
                bn = "আন-নিসা 4:12",
                ru = "Ан-Ниса 4:12",
                de = "An-Nisa' 4:12",
                es = "An-Nisá 4:12",
                uk = "Ан-Ніса 4:12")),
        q("share", 4, 176, 176,
            Tx("آية الكلالة: الإخوة الأشقاء ولأب", "The kalalah verse: full and paternal siblings",
                fr = "Le verset de la kalala : frères et sœurs germains et consanguins",
                tr = "Kelâle ayeti: öz ve baba bir kardeşler",
                ur = "کلالہ کی آیت: حقیقی اور باپ شریک بہن بھائی",
                id = "Ayat kalalah: saudara kandung dan seayah",
                ms = "Ayat kalalah: saudara seibu sebapa dan sebapa",
                fa = "آیه کلاله: برادران و خواهران تنی و پدری",
                bn = "কালালার আয়াত: আপন ও বৈমাত্রেয় ভাইবোন",
                ru = "Аят о калале: полнородные и единокровные братья и сёстры",
                de = "Der Kalala-Vers: Vollgeschwister und Halbgeschwister väterlicherseits",
                es = "La aya de la kalala: hermanos carnales y medio hermanos paternos",
                uk = "Аят про калалу: повнорідні та єдинокровні брати й сестри"),
            Tx("إذا لم يكن للميت ولد ولا والد: للأخت الواحدة النصف، وللأختين فأكثر الثلثان، وإن كانوا إخوة رجالاً ونساءً فللذكر مثل حظ الأنثيين، والأخ يرث أخته كلها إن لم يكن لها ولد.",
                "When the deceased leaves no child and no father: one sister takes a half, two or more take two thirds; if they are brothers and sisters together, a male takes twice a female's share; a brother inherits all of his sister's estate if she has no child.",
                fr = "Lorsque le défunt ne laisse ni enfant ni père : une sœur seule prend la moitié, deux sœurs ou plus prennent les deux tiers ; s'il y a ensemble des frères et des sœurs, l'homme reçoit le double de la part de la femme ; le frère hérite de la totalité des biens de sa sœur si elle n'a pas d'enfant.",
                tr = "Ölenin çocuğu ve babası yoksa: tek kız kardeş yarımı, iki veya daha fazla kız kardeş üçte ikiyi alır; erkek ve kız kardeşler birlikte ise erkeğe kadının payının iki katı verilir; erkek kardeş, çocuğu olmayan kız kardeşinin bütün mirasını alır.",
                ur = "جب میت کی نہ اولاد ہو نہ والد: ایک بہن کو نصف، دو یا زیادہ بہنوں کو دو تہائی؛ اور اگر بھائی اور بہنیں ساتھ ہوں تو مرد کا حصہ عورت سے دوگنا؛ اور بھائی اپنی بہن کے پورے ترکے کا وارث ہوتا ہے اگر اس کی اولاد نہ ہو۔",
                id = "Jika mayit tidak meninggalkan anak dan ayah: satu saudara perempuan mendapat setengah, dua atau lebih mendapat dua pertiga; jika mereka saudara laki-laki dan perempuan bersama-sama, bagian laki-laki dua kali bagian perempuan; saudara laki-laki mewarisi seluruh harta saudara perempuannya jika ia tidak memiliki anak.",
                ms = "Apabila si mati tidak meninggalkan anak dan bapa: seorang saudara perempuan mendapat satu perdua, dua orang atau lebih mendapat dua pertiga; jika mereka saudara lelaki dan perempuan bersama, bahagian lelaki dua kali bahagian perempuan; saudara lelaki mewarisi seluruh harta saudara perempuannya jika dia tiada anak.",
                fa = "هرگاه متوفی نه فرزند داشته باشد نه پدر: یک خواهر نصف، و دو خواهر یا بیشتر دو سوم می‌برند؛ و اگر برادران و خواهران با هم باشند، سهم مرد دو برابر سهم زن است؛ و برادر اگر خواهرش فرزند نداشته باشد، همه ترکه او را به ارث می‌برد.",
                bn = "মৃত ব্যক্তির সন্তান ও পিতা না থাকলে: একজন বোন পায় অর্ধেক, দুই বা ততোধিক বোন পায় দুই-তৃতীয়াংশ; ভাই ও বোন একসঙ্গে থাকলে পুরুষ পায় নারীর দ্বিগুণ; আর বোনের সন্তান না থাকলে ভাই তার সম্পূর্ণ সম্পত্তির ওয়ারিশ হয়।",
                ru = "Если умерший не оставил ни ребёнка, ни отца: одна сестра получает половину, две и более — две трети; если вместе братья и сёстры, мужчина получает вдвое больше женщины; брат наследует всё имущество сестры, если у неё нет ребёнка.",
                de = "Hinterlässt der Verstorbene weder Kind noch Vater: Eine Schwester erhält die Hälfte, zwei oder mehr erhalten zwei Drittel; sind es Brüder und Schwestern zusammen, erhält ein männlicher Erbe doppelt so viel wie ein weiblicher; ein Bruder erbt den gesamten Nachlass seiner Schwester, wenn sie kein Kind hat.",
                es = "Cuando el difunto no deja hijo ni padre: una hermana recibe la mitad; dos o más, dos tercios; si son hermanos y hermanas juntos, el varón recibe el doble de la parte de la mujer; el hermano hereda todos los bienes de su hermana si ella no tiene hijos.",
                uk = "Якщо померлий не залишив ні дитини, ні батька: одна сестра отримує половину, дві й більше — дві третини; якщо разом брати й сестри, чоловік отримує вдвічі більше за жінку; брат успадковує все майно сестри, якщо в неї немає дитини."),
