            Tx("الباقي للعصبة", "The remainder goes to the nearest male agnate",
                fr = "Le reste revient au plus proche agnat masculin",
                tr = "Kalan en yakın erkek asabeye verilir",
                ur = "باقی ترکہ قریب ترین مرد عصبہ کا",
                id = "Sisa untuk 'asabah laki-laki terdekat",
                ms = "Baki untuk asabah lelaki yang paling hampir",
                fa = "باقی‌مانده از آنِ نزدیک‌ترین مرد از عصبه",
                bn = "অবশিষ্ট পায় নিকটতম পুরুষ আসাবা",
                ru = "Остаток — ближайшему родственнику-мужчине по мужской линии",
                de = "Der Rest geht an den nächsten männlichen Agnaten",
                es = "El resto va al agnado varón más cercano",
                uk = "Решта — найближчому родичеві-чоловікові по чоловічій лінії"),
            Tx("بعد أصحاب الفروض يأخذ الباقيَ أقربُ العصبة: الابن ثم ابن الابن، ثم الأب ثم الجد، ثم الإخوة ثم أبناؤهم، ثم الأعمام ثم أبناؤهم.",
                "After the fixed shares, the nearest agnate takes the rest: the son, then the son's son, then the father, then the grandfather, then brothers and their sons, then paternal uncles and their sons.",
                fr = "Après les parts fixes, le plus proche agnat prend le reste : le fils, puis le fils du fils, puis le père, puis le grand-père, puis les frères et leurs fils, puis les oncles paternels et leurs fils.",
                tr = "Farz paylardan sonra kalanı en yakın asabe alır: oğul, sonra oğlun oğlu, sonra baba, sonra dede, sonra erkek kardeşler ve oğulları, sonra amcalar ve oğulları.",
                ur = "اصحاب الفروض کے بعد باقی ترکہ قریب ترین عصبہ لیتا ہے: بیٹا، پھر پوتا، پھر باپ، پھر دادا، پھر بھائی اور ان کے بیٹے، پھر چچا اور ان کے بیٹے۔",
                id = "Setelah bagian-bagian pasti, 'asabah terdekat mengambil sisanya: anak laki-laki, lalu cucu laki-laki dari putra, lalu ayah, lalu kakek, lalu saudara laki-laki dan putra-putra mereka, lalu paman (saudara ayah) dan putra-putra mereka.",
                ms = "Selepas bahagian fardu, asabah yang paling hampir mengambil bakinya: anak lelaki, kemudian cucu lelaki daripada anak lelaki, kemudian bapa, kemudian datuk, kemudian saudara lelaki dan anak-anak lelaki mereka, kemudian bapa saudara sebelah bapa dan anak-anak lelaki mereka.",
                fa = "پس از صاحبان فروض، نزدیک‌ترین عصبه باقی‌مانده را می‌برد: پسر، سپس پسرِ پسر، سپس پدر، سپس پدربزرگ، سپس برادران و پسرانشان، سپس عموها و پسرانشان.",
                bn = "নির্ধারিত অংশের পর অবশিষ্ট পায় নিকটতম আসাবা: পুত্র, তারপর পুত্রের পুত্র, তারপর পিতা, তারপর দাদা, তারপর ভাইয়েরা ও তাদের পুত্ররা, তারপর চাচারা ও তাদের পুত্ররা।",
                ru = "После фиксированных долей остаток получает ближайший агнат: сын, затем сын сына, затем отец, затем дед, затем братья и их сыновья, затем дяди по отцу и их сыновья.",
                de = "Nach den festen Anteilen erhält der nächste Agnat den Rest: der Sohn, dann der Sohn des Sohnes, dann der Vater, dann der Großvater, dann die Brüder und ihre Söhne, dann die Onkel väterlicherseits und ihre Söhne.",
                es = "Tras las cuotas fijas, el agnado más cercano toma el resto: el hijo, luego el hijo del hijo, luego el padre, luego el abuelo, luego los hermanos y sus hijos, luego los tíos paternos y sus hijos.",
                uk = "Після фіксованих часток решту отримує найближчий агнат: син, потім син сина, потім батько, потім дід, потім брати та їхні сини, потім дядьки по батькові та їхні сини."),
            Tx("رواه البخاري (6732) ومسلم (1615)", "Bukhari (6732) and Muslim (1615)",
