        h("family", "«أقضي فيها بما قضى النبي ﷺ: للابنة النصف، ولابنة الابن السدس تكملة الثلثين، وما بقي فللأخت»",
            Tx("بنت الابن مع البنت، والأخوات مع البنات", "A son's daughter with a daughter; sisters with daughters",
                fr = "La fille du fils avec une fille ; les sœurs avec les filles",
                tr = "Kızla birlikte oğlun kızı; kızlarla birlikte kız kardeşler",
                ur = "بیٹی کے ساتھ پوتی، اور بیٹیوں کے ساتھ بہنیں",
                id = "Cucu perempuan dari putra bersama anak perempuan; saudara perempuan bersama anak perempuan",
                ms = "Cucu perempuan bersama anak perempuan; saudara perempuan bersama anak perempuan",
                fa = "دختر پسر همراه با دختر، و خواهران همراه با دختران",
                bn = "কন্যার সঙ্গে পুত্রের কন্যা; কন্যাদের সঙ্গে বোনেরা",
                ru = "Дочь сына вместе с дочерью; сёстры вместе с дочерьми",
                de = "Tochter des Sohnes mit einer Tochter; Schwestern mit Töchtern",
                es = "La hija del hijo con una hija; las hermanas con las hijas",
                uk = "Дочка сина разом із дочкою; сестри разом із дочками"),
            Tx("بنت الابن مع البنت الواحدة لها السدس تكملة للثلثين، والأخوات الشقيقات أو لأب مع البنات عصبة يأخذن الباقي.",
                "A son's daughter with one daughter takes a sixth to complete two thirds, and full or paternal sisters with daughters become residuaries and take the remainder.",
                fr = "La fille du fils, avec une seule fille, prend un sixième pour compléter les deux tiers, et les sœurs germaines ou consanguines, avec des filles, deviennent résiduaires et prennent le reste.",
                tr = "Tek kızla birlikte oğlun kızı, üçte ikiyi tamamlamak için altıda bir alır; öz veya baba bir kız kardeşler de kızlarla birlikte asabe olur ve kalanı alır.",
                ur = "ایک بیٹی کے ساتھ پوتی کو دو تہائی کی تکمیل کے لیے چھٹا حصہ ملتا ہے، اور حقیقی یا باپ شریک بہنیں بیٹیوں کے ساتھ عصبہ بن کر باقی لیتی ہیں۔",
                id = "Cucu perempuan dari putra bersama satu anak perempuan mendapat seperenam untuk melengkapi dua pertiga, dan saudara perempuan kandung atau seayah bersama anak perempuan menjadi 'asabah dan mengambil sisanya.",
                ms = "Cucu perempuan (daripada anak lelaki) bersama seorang anak perempuan mendapat satu perenam bagi menggenapkan dua pertiga, dan saudara perempuan seibu sebapa atau sebapa bersama anak perempuan menjadi asabah dan mengambil baki.",
                fa = "دختر پسر همراه با یک دختر، یک‌ششم می‌برد تا دو سوم کامل شود، و خواهران تنی یا پدری همراه با دختران عصبه می‌شوند و باقی‌مانده را می‌برند.",
                bn = "একজন কন্যার সঙ্গে পুত্রের কন্যা দুই-তৃতীয়াংশ পূরণের জন্য এক-ষষ্ঠাংশ পায়, আর আপন বা বৈমাত্রেয় বোনেরা কন্যাদের সঙ্গে আসাবা হয়ে অবশিষ্ট পায়।",
                ru = "Дочь сына вместе с единственной дочерью получает шестую в дополнение до двух третей, а полнородные или единокровные сёстры вместе с дочерьми становятся асаба и получают остаток.",
                de = "Die Tochter des Sohnes erhält neben einer einzigen Tochter ein Sechstel zur Ergänzung der zwei Drittel, und Vollschwestern oder Halbschwestern väterlicherseits werden neben Töchtern zu Resterben und erhalten den Rest.",
                es = "La hija del hijo, junto a una sola hija, recibe un sexto para completar los dos tercios, y las hermanas carnales o paternas, junto a las hijas, pasan a ser residuarias y toman el resto.",
                uk = "Дочка сина разом з єдиною дочкою отримує шосту як доповнення до двох третин, а повнорідні або єдинокровні сестри разом із дочками стають асаба й отримують решту."),
