            Tx("الجدة والجد", "Grandmother and grandfather",
                fr = "La grand-mère et le grand-père",
                tr = "Nine ve dede",
                ur = "جدہ اور دادا",
                id = "Nenek dan kakek",
                ms = "Nenek dan datuk",
                fa = "مادربزرگ و پدربزرگ",
                bn = "দাদি-নানি ও দাদা",
                ru = "Бабушка и дед",
                de = "Großmutter und Großvater",
                es = "La abuela y el abuelo",
                uk = "Бабуся й дід"),
            Tx("أعطى النبي ﷺ الجدة السدس كما شهد بذلك المغيرة ومحمد بن مسلمة (أبو داود 2894)، وعليه الإجماع إذا لم تكن الأم. والجد أبو الأب يقوم مقام الأب عند عدمه، واختلفوا في الجد مع الإخوة.",
                "The Prophet ﷺ gave the grandmother a sixth, as al-Mughirah and Muhammad ibn Maslamah testified (Abu Dawud 2894), and there is consensus on it when there is no mother. The paternal grandfather takes the father's place when there is no father; scholars differ on the grandfather with siblings.",
                fr = "Le Prophète ﷺ a donné un sixième à la grand-mère, comme en ont témoigné al-Mughira et Muhammad ibn Maslama (Abou Dawoud 2894), et il y a consensus là-dessus en l'absence de la mère. Le grand-père paternel prend la place du père en l'absence de celui-ci ; les savants divergent sur le grand-père avec les frères et sœurs.",
                tr = "Peygamber ﷺ nineye altıda bir vermiştir; Muğîre ve Muhammed b. Mesleme buna şahitlik etmiştir (Ebû Dâvûd 2894). Anne yoksa bu konuda icmâ vardır. Babanın babası olan dede, baba yokken onun yerini alır; dedenin kardeşlerle birlikte durumu konusunda âlimler ihtilaf etmiştir.",
                ur = "نبی ﷺ نے جدہ کو چھٹا حصہ دیا، جیسا کہ مغیرہ اور محمد بن مسلمہ نے اس کی گواہی دی (ابو داود 2894)، اور ماں نہ ہو تو اس پر اجماع ہے۔ دادا باپ کی عدم موجودگی میں اس کا قائم مقام ہوتا ہے؛ دادا کے ساتھ بہن بھائیوں کے بارے میں علماء کا اختلاف ہے۔",
                id = "Nabi ﷺ memberi nenek seperenam, sebagaimana disaksikan oleh al-Mughirah dan Muhammad bin Maslamah (Abu Dawud 2894), dan ada ijmak tentang hal itu jika tidak ada ibu. Kakek dari ayah menempati posisi ayah jika ayah tidak ada; ulama berbeda pendapat tentang kakek bersama saudara.",
                ms = "Nabi ﷺ memberikan nenek satu perenam, sebagaimana disaksikan oleh al-Mughirah dan Muhammad bin Maslamah (Abu Daud 2894), dan ada ijmak mengenainya jika tiada ibu. Datuk sebelah bapa menggantikan tempat bapa jika bapa tiada; ulama berbeza pendapat tentang datuk bersama adik-beradik.",
                fa = "پیامبر ﷺ به مادربزرگ یک‌ششم داد، چنان‌که مغیره و محمد بن مسلمه بر آن گواهی دادند (ابوداود 2894)، و در صورت نبودن مادر بر آن اجماع است. پدربزرگ پدری در نبودِ پدر جانشین او می‌شود؛ و درباره پدربزرگ همراه با برادران و خواهران اختلاف است.",
                bn = "নবী ﷺ দাদি-নানিকে এক-ষষ্ঠাংশ দিয়েছেন, যেমন মুগিরা ও মুহাম্মাদ ইবনে মাসলামা সাক্ষ্য দিয়েছেন (আবু দাউদ 2894), আর মাতা না থাকলে এ বিষয়ে ইজমা রয়েছে। পিতা না থাকলে দাদা পিতার স্থলাভিষিক্ত হন; ভাইবোনের সঙ্গে দাদার বিষয়ে আলেমদের মতভেদ আছে।",
                ru = "Пророк ﷺ дал бабушке шестую, как засвидетельствовали аль-Мугира и Мухаммад ибн Маслама (Абу Дауд 2894), и в этом есть иджма, если нет матери. Дед по отцу занимает место отца при его отсутствии; учёные расходятся во мнениях о деде вместе с братьями и сёстрами.",
                de = "Der Prophet ﷺ gab der Großmutter ein Sechstel, wie al-Mughira und Muhammad ibn Maslama bezeugten (Abu Dawud 2894), und darüber besteht Konsens, wenn keine Mutter vorhanden ist. Der Großvater väterlicherseits tritt an die Stelle des Vaters, wenn dieser fehlt; über den Großvater mit Geschwistern sind die Gelehrten uneins.",
                es = "El Profeta ﷺ dio a la abuela un sexto, como atestiguaron al-Mughira y Muhammad ibn Maslama (Abu Dawud 2894), y hay consenso al respecto cuando no hay madre. El abuelo paterno ocupa el lugar del padre cuando este falta; los sabios difieren sobre el abuelo con hermanos.",
                uk = "Пророк ﷺ дав бабусі шосту, як засвідчили аль-Мугіра та Мухаммад ібн Маслама (Абу Дауд 2894), і щодо цього є іджма, якщо немає матері. Дід по батькові заступає батька за його відсутності; учені розходяться в думках щодо діда разом із братами й сестрами."),
            Tx("الإجماع لابن المنذر؛ المغني", "Ibn al-Mundhir, al-Ijma'; al-Mughni",
                fr = "Ibn al-Mundhir, al-Ijma' ; al-Mughni",
