                ms = "Ibn al-Munzir, al-Ijma'; al-Mughni",
                fa = "ابن منذر، الإجماع؛ المغنی",
                bn = "ইবনুল মুনজির, আল-ইজমা; আল-মুগনি",
                ru = "Ибн аль-Мунзир, «аль-Иджма»; «аль-Мугни»",
