                tr = "Vasiyet üçte birle sınırlıdır",
                ur = "وصیت ایک تہائی کی حد تک",
                id = "Wasiat dibatasi sepertiga",
                ms = "Wasiat terhad kepada satu pertiga",
                fa = "وصیت تا سقف یک‌سوم",
                bn = "অসিয়ত এক-তৃতীয়াংশের মধ্যে সীমিত",
                ru = "Завещание ограничено третью",
