            Tx("لا تزيد الوصية على ثلث التركة إلا بإجازة الورثة، ولا وصية لوارث (أبو داود 2870، الترمذي 2120).",
                "A bequest may not exceed a third of the estate unless the heirs consent, and there is no bequest to an heir (Abu Dawud 2870, al-Tirmidhi 2120).",
                fr = "Un legs ne peut dépasser le tiers de la succession sans le consentement des héritiers, et il n'y a pas de legs en faveur d'un héritier (Abou Dawoud 2870, at-Tirmidhi 2120).",
                tr = "Vasiyet, mirasçılar onaylamadıkça terikenin üçte birini aşamaz ve mirasçıya vasiyet yoktur (Ebû Dâvûd 2870, Tirmizî 2120).",
                ur = "وصیت ورثاء کی اجازت کے بغیر ترکے کے ایک تہائی سے زیادہ نہیں ہو سکتی، اور وارث کے لیے کوئی وصیت نہیں (ابو داود 2870، ترمذی 2120)۔",
                id = "Wasiat tidak boleh melebihi sepertiga harta peninggalan kecuali dengan persetujuan ahli waris, dan tidak ada wasiat untuk ahli waris (Abu Dawud 2870, at-Tirmidzi 2120).",
                ms = "Wasiat tidak boleh melebihi satu pertiga harta pusaka kecuali dengan persetujuan waris, dan tiada wasiat untuk waris (Abu Daud 2870, al-Tirmizi 2120).",
