                fr = "L'application suit la majorité sur l'exclusion, le 'awl, le radd et les deux 'Umariyya, et signale les cas controversés comme le grand-père avec les frères et sœurs et al-Mushtaraka. Pour les successions importantes ou complexes, consultez un tribunal de la charia ou un savant qualifié.",
