                ur = "ایپ حجب، عول، رد اور عمریتین میں جمہور کے قول پر حساب کرتی ہے، اور اختلافی صورتوں جیسے دادا کے ساتھ بہن بھائی اور مسئلۂ مشترکہ کی نشاندہی کرتی ہے۔ بڑے یا پیچیدہ ترکوں میں شرعی عدالت یا کسی ماہر عالم سے رجوع کرنا زیادہ محتاط ہے۔",
                id = "Aplikasi mengikuti jumhur dalam hijab, 'aul, radd, dan 'Umariyyatain, serta menjelaskan kasus yang diperselisihkan seperti kakek bersama saudara dan al-Musytarakah. Untuk harta warisan yang besar atau rumit, rujuklah ke pengadilan agama atau ulama yang ahli.",
                ms = "Aplikasi mengikut jumhur dalam hijab, 'aul, radd dan 'Umariyyatan, serta menerangkan kes yang diperselisihkan seperti datuk bersama adik-beradik dan al-Musytarakah. Bagi harta pusaka yang besar atau rumit, rujuklah Mahkamah Syariah atau ulama yang berkelayakan.",
                fa = "برنامه در حجب، عول، رد و عُمَریّتین بر اساس قول جمهور محاسبه می‌کند و موارد اختلافی مانند جد همراه با برادران و خواهران و مسئله مشترکه را بیان می‌کند. در ترکه‌های بزرگ یا پیچیده، احتیاط آن است که به دادگاه شرعی یا عالم متخصص مراجعه کنید.",
                bn = "অ্যাপ হাজব, আওল, রদ ও উমারিয়্যাতাইনে জমহুরের মত অনুসারে হিসাব করে, এবং দাদার সঙ্গে ভাইবোন ও মুশতারাকার মতো মতভেদপূর্ণ বিষয়গুলো উল্লেখ করে। বড় বা জটিল সম্পত্তির ক্ষেত্রে শরিয়া আদালত বা যোগ্য আলেমের সঙ্গে পরামর্শ করুন।",
                ru = "Приложение следует мнению большинства в вопросах исключения из наследства, ауля, радда и двух «умариййа», а также указывает спорные случаи, такие как дед вместе с братьями и сёстрами и «аль-муштарака». При крупном или сложном наследстве обратитесь в шариатский суд или к квалифицированному учёному.",
                de = "Die App folgt der Mehrheit bei Ausschluss, 'Awl, Radd und den beiden 'Umariyya-Fällen und weist auf umstrittene Fälle hin, etwa den Großvater mit Geschwistern und al-Muschtaraka. Bei großen oder komplexen Nachlässen wende dich an ein Scharia-Gericht oder einen qualifizierten Gelehrten.",
                es = "La app sigue a la mayoría en la exclusión, el 'awl, el radd y las dos 'Umariyya, y señala los casos discutidos, como el abuelo con hermanos y al-Mushtaraka. Para herencias grandes o complejas, consulta a un tribunal islámico (de la sharía) o a un sabio cualificado.",
                uk = "Застосунок дотримується думки більшості щодо усунення від спадщини, аулю, радду та двох «умаріййа», а також указує спірні випадки, як-от дід разом із братами й сестрами та «аль-муштарака». У разі великої чи складної спадщини зверніться до шаріатського суду або до кваліфікованого вченого."),
