                tr = "Vakitler buna göre hesaplanır: öğle için güneşin zevali, ikindi için bir cismin gölgesi, akşam için güneşin batışı, yatsı için şafağın kaybolması ve sabah için fecr-i sâdık.",
                ur = "اسی کے مطابق اوقات کا حساب ہوتا ہے: ظہر کے لیے زوال، عصر کے لیے چیز کا سایہ، مغرب کے لیے غروب آفتاب، عشاء کے لیے شفق کا غائب ہونا، اور فجر کے لیے صبح صادق۔",
                id = "Waktu salat dihitung berdasarkan hadis ini: tergelincirnya matahari untuk Zuhur, bayangan benda untuk Asar, terbenamnya matahari untuk Magrib, hilangnya mega merah untuk Isya, dan fajar sadik untuk Subuh.",
                ms = "Waktu solat dikira berdasarkannya: gelincir matahari untuk Zohor, bayang-bayang objek untuk Asar, terbenam matahari untuk Maghrib, hilangnya syafak untuk Isyak, dan fajar sadiq untuk Subuh.",
                fa = "اوقات بر اساس آن محاسبه می‌شود: زوال برای ظهر، سایه شیء برای عصر، غروب خورشید برای مغرب، ناپدید شدن شفق برای عشا و طلوع فجر صادق برای صبح.",
                bn = "এর ভিত্তিতেই সময় হিসাব করা হয়: যোহরের জন্য সূর্য হেলে পড়া, আসরের জন্য বস্তুর ছায়া, মাগরিবের জন্য সূর্যাস্ত, এশার জন্য লালিমা অদৃশ্য হওয়া, আর ফজরের জন্য সুবহে সাদিক।",
                ru = "По нему рассчитывается время намазов: зенит солнца — для Зухра, тень предмета — для Асра, заход солнца — для Магриба, исчезновение вечерней зари — для Иши и истинный рассвет — для Фаджра.",
                de = "Danach werden die Zeiten berechnet: der Zenit der Sonne für Dhuhr, der Schatten eines Gegenstands für Asr, der Sonnenuntergang für Maghrib, das Verschwinden der Abendröte für Ischa und die wahre Morgendämmerung für Fadschr.",
                es = "Según él se calculan los horarios: el cenit del sol para Dhuhr, la sombra de un objeto para Asr, la puesta del sol para Maghrib, la desaparición del crepúsculo para Isha y el alba verdadera para Fajr.",
                uk = "За ним обчислюють час намазів: зеніт сонця — для Зухру, тінь предмета — для Асру, захід сонця — для Магрібу, зникнення вечірньої зорі — для Іші та справжній світанок — для Фаджру."),
