            Tx("يبدأ العصر عند الجمهور إذا صار ظل الشيء مثله، وعند الحنفية مثليه. وتختلف الهيئات في درجة انخفاض الشمس للفجر والعشاء (رابطة العالم الإسلامي 18° و17°، وأم القرى 18.5° والعشاء بعد المغرب بتسعين دقيقة)، ولذلك يتيح التطبيق اختيار الطريقة المعتمدة في بلدك.",
                "Asr begins, for the majority, when an object's shadow equals its length, and for the Hanafis when it is twice its length. Organizations differ on the sun's depression for Fajr and Isha (Muslim World League 18° and 17°, Umm al-Qura 18.5° and Isha 90 minutes after Maghrib), so the app lets you choose the method used in your country.",
                fr = "Selon la majorité, Asr commence lorsque l'ombre d'un objet égale sa longueur, et selon les hanafites lorsqu'elle en atteint le double. Les organismes divergent sur l'abaissement du soleil pour Fajr et Icha (Ligue islamique mondiale 18° et 17°, Umm al-Qura 18,5° et Icha 90 minutes après Maghrib) ; l'application vous laisse donc choisir la méthode suivie dans votre pays.",
                tr = "İkindi, cumhura göre bir cismin gölgesi kendi boyu kadar olunca, Hanefîlere göre iki katı olunca başlar. Kurumlar sabah ve yatsı için güneşin ufkun altındaki derecesinde farklılık gösterir (Müslüman Dünya Birliği 18° ve 17°, Ümmü'l-Kurâ 18,5° ve yatsı akşamdan 90 dakika sonra); bu yüzden uygulama ülkenizde kullanılan yöntemi seçmenize imkân verir.",
                ur = "جمہور کے نزدیک عصر اس وقت شروع ہوتی ہے جب چیز کا سایہ اس کے برابر ہو جائے، اور احناف کے نزدیک جب دوگنا ہو جائے۔ فجر اور عشاء کے لیے سورج کے افق سے نیچے کے زاویے میں ادارے مختلف ہیں (رابطہ عالم اسلامی 18° اور 17°، ام القریٰ 18.5° اور عشاء مغرب کے 90 منٹ بعد)، اس لیے ایپ آپ کو اپنے ملک میں رائج طریقہ منتخب کرنے دیتی ہے۔",
                id = "Menurut jumhur, Asar dimulai ketika bayangan benda sama dengan panjangnya, dan menurut mazhab Hanafi ketika dua kali panjangnya. Lembaga-lembaga berbeda dalam sudut depresi matahari untuk Subuh dan Isya (Liga Muslim Dunia 18° dan 17°, Umm al-Qura 18,5° dan Isya 90 menit setelah Magrib), sehingga aplikasi memberi Anda pilihan metode yang dipakai di negara Anda.",
                ms = "Menurut jumhur, Asar bermula apabila bayang-bayang objek sama panjang dengannya, dan menurut mazhab Hanafi apabila dua kali panjangnya. Badan-badan berbeza tentang darjah kedudukan matahari di bawah ufuk untuk Subuh dan Isyak (Liga Muslim Sedunia 18° dan 17°, Umm al-Qura 18.5° dan Isyak 90 minit selepas Maghrib), maka aplikasi membenarkan anda memilih kaedah yang digunakan di negara anda.",
                fa = "نزد جمهور، عصر وقتی آغاز می‌شود که سایه شیء به اندازه خودش شود، و نزد حنفیه وقتی که دو برابر شود. نهادها در زاویه پایین بودن خورشید برای صبح و عشا اختلاف دارند (رابطه جهان اسلام 18° و 17°، ام‌القری 18.5° و عشا نود دقیقه پس از مغرب)؛ از این رو برنامه به شما امکان می‌دهد روش رایج در کشورتان را انتخاب کنید.",
                bn = "জমহুরের মতে আসর শুরু হয় যখন বস্তুর ছায়া তার সমান হয়, আর হানাফিদের মতে যখন দ্বিগুণ হয়। ফজর ও এশার জন্য দিগন্তের নিচে সূর্যের কোণ নিয়ে সংস্থাগুলোর মধ্যে পার্থক্য আছে (মুসলিম ওয়ার্ল্ড লীগ 18° ও 17°, উম্মুল কুরা 18.5° এবং মাগরিবের 90 মিনিট পর এশা), তাই অ্যাপে আপনি আপনার দেশে প্রচলিত পদ্ধতি বেছে নিতে পারেন।",
                ru = "По мнению большинства, Аср начинается, когда тень предмета равна его длине, а по мнению ханафитов — когда она вдвое длиннее. Организации расходятся в угле погружения солнца для Фаджра и Иши (Лига исламского мира 18° и 17°, Умм аль-Кура 18,5° и Иша через 90 минут после Магриба), поэтому приложение позволяет выбрать метод, принятый в вашей стране.",
                de = "Asr beginnt nach der Mehrheit, wenn der Schatten eines Gegenstands seiner Länge entspricht, nach den Hanafiten, wenn er doppelt so lang ist. Die Organisationen unterscheiden sich beim Sonnenstand unter dem Horizont für Fadschr und Ischa (Islamische Weltliga 18° und 17°, Umm al-Qura 18,5° und Ischa 90 Minuten nach Maghrib); daher kannst du in der App die in deinem Land übliche Methode wählen.",
                es = "Según la mayoría, el Asr comienza cuando la sombra de un objeto iguala su longitud, y según los hanafíes cuando la duplica. Los organismos difieren en la depresión del sol para Fajr e Isha (Liga Mundial Musulmana 18° y 17°, Umm al-Qura 18,5° e Isha 90 minutos después del Maghrib), por eso la app te deja elegir el método que se usa en tu país.",
                uk = "За думкою більшості, Аср починається, коли тінь предмета дорівнює його довжині, а за думкою ханафітів — коли вона вдвічі довша. Організації розходяться щодо кута занурення сонця для Фаджру та Іші (Ліга ісламського світу 18° і 17°, Умм аль-Кура 18,5° та Іша через 90 хвилин після Магрібу), тому застосунок дає змогу вибрати метод, прийнятий у вашій країні."),
