        f(ProofKind.SCHOLARS, "fingers",
            Tx("العدّ بالأصابع والمسبحة", "Counting on fingers or with a counter",
                fr = "Compter sur les doigts ou avec un compteur",
                tr = "Parmakla veya sayaçla saymak",
                ur = "انگلیوں پر یا کاؤنٹر سے گننا",
                id = "Menghitung dengan jari atau dengan alat penghitung",
                ms = "Mengira dengan jari atau dengan pembilang",
                fa = "شمردن با انگشتان یا با شمارنده",
                bn = "আঙুলে বা কাউন্টারে গণনা",
                ru = "Счёт на пальцах или счётчиком",
                de = "Zählen mit den Fingern oder mit einem Zähler",
                es = "Contar con los dedos o con un contador",
                uk = "Лік на пальцях або лічильником"),
            Tx("عدّ الذكر بالأنامل أفضل لحديث «واعقدن بالأنامل فإنهن مسؤولات مستنطقات» (أبو داود 1501، الترمذي 3583)، واستعمال المسبحة والعدّاد جائز عند جمهور العلماء.",
                "Counting on the fingers is better, per the hadith «count on your fingertips, for they will be questioned and made to speak» (Abu Dawud 1501, al-Tirmidhi 3583); using beads or a counter is permissible according to most scholars.",
                fr = "Compter sur les doigts est meilleur, d'après le hadith « comptez sur le bout de vos doigts, car ils seront interrogés et amenés à parler » (Abou Dawoud 1501, at-Tirmidhi 3583) ; utiliser un chapelet ou un compteur est permis selon la plupart des savants.",
                tr = "Zikri parmak uçlarıyla saymak daha faziletlidir; hadiste «Parmak uçlarınızla sayın, çünkü onlar sorguya çekilecek ve konuşturulacaktır» buyrulmuştur (Ebû Dâvûd 1501, Tirmizî 3583). Tespih veya sayaç kullanmak âlimlerin çoğuna göre caizdir.",
                ur = "ذکر کو انگلیوں کے پوروں پر گننا افضل ہے، حدیث کی بنا پر «انگلیوں کے پوروں پر گنا کرو، کیونکہ ان سے پوچھا جائے گا اور انہیں بلوایا جائے گا» (ابو داود 1501، ترمذی 3583)؛ اور تسبیح کے دانوں یا کاؤنٹر کا استعمال جمہور علماء کے نزدیک جائز ہے۔",
                id = "Menghitung zikir dengan ujung jari lebih utama, berdasarkan hadis «hitunglah dengan ujung jari, karena jari-jari itu akan ditanya dan diminta berbicara» (Abu Dawud 1501, at-Tirmidzi 3583); menggunakan biji tasbih atau alat penghitung boleh menurut jumhur ulama.",
                ms = "Mengira zikir dengan hujung jari lebih utama, berdasarkan hadis «kiralah dengan hujung jari, kerana ia akan ditanya dan diminta bercakap» (Abu Daud 1501, al-Tirmizi 3583); menggunakan biji tasbih atau pembilang adalah harus menurut jumhur ulama.",
                fa = "شمردن ذکر با سرانگشتان بهتر است، به دلیل حدیث «با سرانگشتان بشمارید، زیرا از آن‌ها پرسیده می‌شود و به سخن درمی‌آیند» (ابوداود 1501، ترمذی 3583)؛ و استفاده از تسبیح یا شمارنده نزد جمهور علما جایز است.",
                bn = "আঙুলের ডগায় জিকির গণনা করা উত্তম, এই হাদিসের কারণে: «আঙুলের ডগায় গণনা করো, কেননা তাদের জিজ্ঞাসা করা হবে এবং কথা বলানো হবে» (আবু দাউদ 1501, তিরমিজি 3583); তাসবিহের দানা বা কাউন্টার ব্যবহার জমহুর আলেমের মতে জায়েজ।",
                ru = "Считать зикр на пальцах лучше, согласно хадису: «Считайте на кончиках пальцев, ведь они будут спрошены и им будет дана речь» (Абу Дауд 1501, ат-Тирмизи 3583); пользоваться чётками или счётчиком дозволено по мнению большинства учёных.",
                de = "Das Zählen mit den Fingern ist besser, gemäß dem Hadith „Zählt mit den Fingerspitzen, denn sie werden befragt und zum Sprechen gebracht“ (Abu Dawud 1501, at-Tirmidhi 3583); eine Gebetskette oder einen Zähler zu benutzen ist nach den meisten Gelehrten erlaubt.",
                es = "Contar con los dedos es mejor, según el hadiz «contad con las yemas de los dedos, pues serán interrogadas y se les hará hablar» (Abu Dawud 1501, at-Tirmidhi 3583); usar un rosario o un contador está permitido según la mayoría de los sabios.",
                uk = "Лічити зікр на пальцях краще, згідно з хадисом: «Лічіть на кінчиках пальців, адже їх буде запитано й їм буде дано мову» (Абу Дауд 1501, ат-Тірмізі 3583); користуватися чотками чи лічильником дозволено за думкою більшості вчених."),
            Tx("مجموع الفتاوى لابن تيمية", "Ibn Taymiyyah, Majmu' al-Fatawa",
                fr = "Ibn Taymiyya, Majmu' al-Fatawa",
                tr = "İbn Teymiyye, Mecmû'u'l-Fetâvâ",
                ur = "ابن تیمیہ، مجموع الفتاویٰ",
                id = "Ibnu Taimiyah, Majmu' al-Fatawa",
                ms = "Ibn Taimiyyah, Majmu' al-Fatawa",
                fa = "ابن تیمیه، مجموع الفتاوی",
                bn = "ইবনে তাইমিয়া, মাজমুউল ফাতাওয়া",
                ru = "Ибн Таймия, «Маджму аль-фатава»",
                de = "Ibn Taimiyya, Madschmu' al-Fatawa",
                es = "Ibn Taymiyya, Maymu' al-Fatawa",
