                bn = "আবু দাউদ (4403) ও তিরমিজি (1423)",
                ru = "Абу Дауд (4403) и ат-Тирмизи (1423)",
                de = "Abu Dawud (4403) und at-Tirmidhi (1423)",
                es = "Abu Dawud (4403) y at-Tirmidhi (1423)",
                uk = "Абу Дауд (4403) і ат-Тірмізі (1423)")),
        f(ProofKind.SCHOLARS, "age",
            Tx("السن الهجري", "Age in Hijri years",
                fr = "L'âge en années hégiriennes",
                tr = "Hicri yıl olarak yaş",
                ur = "ہجری سالوں میں عمر",
                id = "Usia dalam tahun Hijriah",
                ms = "Umur dalam tahun Hijrah",
                fa = "سن به سال هجری قمری",
                bn = "হিজরি বছরে বয়স",
                ru = "Возраст в годах по хиджре",
                de = "Alter in Hidschra-Jahren",
                es = "La edad en años hiyri",
                uk = "Вік у роках за хіджрою"),
            Tx("إذا لم تظهر علامات البلوغ فحدّه عند الجمهور خمس عشرة سنة هجرية، لحديث ابن عمر في البخاري (2664)، وعند أبي حنيفة ثماني عشرة. ولذلك يعرض التطبيق العمر بالهجري أيضاً.",
                "If the signs of puberty do not appear, the majority set it at fifteen Hijri years, per Ibn Umar's hadith in Bukhari (2664), and Abu Hanifa at eighteen. That is why the app also shows your age in Hijri years.",
                fr = "Si les signes de la puberté n'apparaissent pas, la majorité la fixe à quinze années hégiriennes, d'après le hadith d'Ibn Omar chez Al-Boukhari (2664), et Abou Hanifa à dix-huit. C'est pourquoi l'application affiche aussi votre âge en années hégiriennes.",
                tr = "Ergenlik belirtileri ortaya çıkmazsa cumhur, Buhârî'deki (2664) İbn Ömer hadisine dayanarak bunu on beş hicri yıl, Ebû Hanîfe ise on sekiz olarak belirler. Bu yüzden uygulama yaşınızı hicri yıl olarak da gösterir.",
                ur = "اگر بلوغت کی علامات ظاہر نہ ہوں تو جمہور کے نزدیک اس کی حد پندرہ ہجری سال ہے، بخاری (2664) میں ابن عمر کی حدیث کی بنا پر، اور ابو حنیفہ کے نزدیک اٹھارہ سال۔ اسی لیے ایپ آپ کی عمر ہجری سالوں میں بھی دکھاتی ہے۔",
                id = "Jika tanda-tanda balig tidak tampak, jumhur menetapkannya pada usia lima belas tahun Hijriah, berdasarkan hadis Ibnu Umar dalam Bukhari (2664), sedangkan Abu Hanifah delapan belas tahun. Karena itu aplikasi juga menampilkan usia Anda dalam tahun Hijriah.",
